package rail0_test

import (
	"encoding/hex"
	"strings"
	"testing"

	rail0 "github.com/commercelayer/rail0-go"
	"golang.org/x/crypto/sha3"
)

// Every generated bytes32 must be keccak256("rail0.dispute.<code>"), the rule the
// gateway and the contract derive it by — a regenerated table that drifted from it
// would send a reason the gateway reads as unrecognised.
func TestDisputeReasonDictionaries_Bytes32IsTheDerivedHash(t *testing.T) {
	lists := map[string][]rail0.DisputeReasonInfo{
		"open":   rail0.DisputeOpenReasons,
		"close":  rail0.DisputeCloseReasons,
		"system": rail0.DisputeSystemCloseReasons,
	}
	for kind, list := range lists {
		if len(list) == 0 {
			t.Fatalf("%s: empty dictionary", kind)
		}
		for _, e := range list {
			h := sha3.NewLegacyKeccak256()
			h.Write([]byte("rail0.dispute." + string(e.Code)))
			want := "0x" + hex.EncodeToString(h.Sum(nil))
			if e.Bytes32 != want {
				t.Errorf("%s %s: bytes32 %s, want %s", kind, e.Code, e.Bytes32, want)
			}
			if e.Description == "" {
				t.Errorf("%s %s: empty description", kind, e.Code)
			}
		}
	}
	if len(rail0.DisputeOpenReasons) != 9 || len(rail0.DisputeCloseReasons) != 4 || len(rail0.DisputeSystemCloseReasons) != 1 {
		t.Errorf("sizes: open %d, close %d, system %d; want 9, 4, 1",
			len(rail0.DisputeOpenReasons), len(rail0.DisputeCloseReasons), len(rail0.DisputeSystemCloseReasons))
	}
}

func TestLookupDisputeReason(t *testing.T) {
	notReceived := rail0.DisputeOpenReasons[0]
	cases := []struct {
		name   string
		lookup func(string) (rail0.DisputeReasonInfo, bool)
		in     string
		want   rail0.DisputeReason
		ok     bool
	}{
		{"open code", rail0.LookupDisputeOpenReason, "not_received", rail0.DisputeOpenReasonNotReceived, true},
		{"open bytes32", rail0.LookupDisputeOpenReason, notReceived.Bytes32, rail0.DisputeOpenReasonNotReceived, true},
		{"open bytes32 upper hex", rail0.LookupDisputeOpenReason, "0x" + strings.ToUpper(notReceived.Bytes32[2:]), rail0.DisputeOpenReasonNotReceived, true},
		{"open trims spaces", rail0.LookupDisputeOpenReason, " duplicate ", rail0.DisputeOpenReasonDuplicate, true},
		{"open rejects a close code", rail0.LookupDisputeOpenReason, "withdrawn", "", false},
		{"open code is case-sensitive", rail0.LookupDisputeOpenReason, "Not_Received", "", false},
		{"open rejects empty", rail0.LookupDisputeOpenReason, "", "", false},
		{"close code", rail0.LookupDisputeCloseReason, "item_received", rail0.DisputeCloseReasonItemReceived, true},
		{"close other", rail0.LookupDisputeCloseReason, "other", rail0.DisputeCloseReasonOther, true},
		{"close rejects the system reason", rail0.LookupDisputeCloseReason, "full_refund", "", false},
		{"close rejects the system bytes32", rail0.LookupDisputeCloseReason, rail0.DisputeSystemCloseReasons[0].Bytes32, "", false},
		{"close rejects the zero word", rail0.LookupDisputeCloseReason, "0x" + strings.Repeat("0", 64), "", false},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got, ok := c.lookup(c.in)
			if ok != c.ok || got.Code != c.want {
				t.Errorf("got (%q, %v), want (%q, %v)", got.Code, ok, c.want, c.ok)
			}
		})
	}
	// `other` is in both lists with different descriptions: the kind picks which.
	o, _ := rail0.LookupDisputeOpenReason("other")
	c, _ := rail0.LookupDisputeCloseReason("other")
	if o.Description == c.Description || o.Bytes32 != c.Bytes32 {
		t.Errorf("other: open %q/%s, close %q/%s", o.Description, o.Bytes32, c.Description, c.Bytes32)
	}
}
